code = '''
using System;
using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// 1. Strongly-typed metadata via the generic GetTypeInfo<T>()
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($\"Got typed metadata: {personInfo.Type.Name}, kind = {personInfo.Kind}\");

// 2. Probe without throwing via TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($\"TryGetTypeInfo succeeded for Person: {info!.Type.Name}\");
}

// Try a type that won't resolve — use a resolver that only handles Person
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine()   // empty: resolves nothing
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
{
    Console.WriteLine(\"Unexpectedly found metadata!\");
}
else
{
    Console.WriteLine(\"TryGetTypeInfo correctly returned false — no metadata for Person\");
}

record Person(string Name, int Age);
'''
with open('Program.cs', 'w') as f:
    f.write(code)
